#!/usr/bin/env python3
"""Pack assets/textures/*.png into js/textures.js as data URIs.

Run from the repo root:  python3 tools/build_textures.py
"""
import base64, json, pathlib

root = pathlib.Path(__file__).resolve().parent.parent
tex = {}
for p in sorted((root / "assets" / "textures").glob("*.png")):
    tex[p.stem] = "data:image/png;base64," + base64.b64encode(p.read_bytes()).decode()
out = root / "js" / "textures.js"
out.write_text(
    "// Generated by tools/build_textures.py. Do not edit by hand.\n"
    "// Textures: Minetest Game + Mesecons, CC BY-SA 3.0. See CREDITS.md.\n"
    "window.BP_TEX = " + json.dumps(tex, indent=0) + ";\n"
)
print(f"wrote {out.relative_to(root)} with {len(tex)} textures, {out.stat().st_size} bytes")
